def longest_word_chain(words):
 dp={};answer=0
 for word in sorted(words,key=len):
  dp[word]=1+max((dp.get(word[:i]+word[i+1:],0) for i in range(len(word))),default=0);answer=max(answer,dp[word])
 return answer

